export function relatedSymmetryExercises(lesson,exercises=[]){
  if(!lesson)return [];
  if(Array.isArray(lesson.derivationIds))return lesson.derivationIds.map(id=>exercises.find(item=>item.id===id)).filter(Boolean);
  const bound=exercises.filter(item=>item.lessonId===lesson.id||item.lessonIds?.includes(lesson.id));
  if(bound.length)return bound;
  return lesson.labPreset?exercises.filter(item=>item.lab===lesson.lab&&item.labPreset===lesson.labPreset):[];
}
